  permission_allowed: { en: '✅ Allowed, continuing...', zh: '✅ 已允许，继续执行...', 'zh-TW': '✅ 已允許，繼續執行...', ja: '✅ 許可しました。続行中...', es: '✅ Permitido, continuando...' },
